#include <assert.h>
#include "../src/c/history_progress.h"
int main(void){assert(graph_x_coordinate(0,1,144)==72);assert(graph_x_coordinate(0,2,144)==0&&graph_x_coordinate(1,2,144)==143);for(int width=144;width<=180;width+=8)assert(graph_x_coordinate(0,1,width)>=0&&graph_x_coordinate(0,1,width)<width);CalendarResponse c={1,2024,2,29,0,0,0};assert(calendar_response_valid(&c,1,2024,2));c.days=28;assert(!calendar_response_valid(&c,1,2024,2));c.days=29;c.mask=1u<<29;assert(!calendar_response_valid(&c,1,2024,2));ProgressAssembly a;progress_assembly_reset(&a);assert(progress_chunk_add(&a,2,0,0,0,0,1,0,0));assert(progress_assembly_complete(&a)&&a.total_points==0);progress_assembly_reset(&a);ProgressPoint p[2]={{1,100},{2,90}};assert(progress_chunk_add(&a,3,0,0,1,0,1,2,p));assert(progress_assembly_complete(&a)&&a.total_points==2);assert(!progress_chunk_add(&a,3,0,0,1,0,1,2,(ProgressPoint[]){{1,101},{2,90}}));assert(graph_coordinate(100,90,100,20)==0&&graph_coordinate(90,90,100,20)==19);int32_t lo,hi;graph_axis_bounds(180,195,false,&lo,&hi);assert(lo<180&&hi>195&&lo>0);graph_axis_bounds(1,2,false,&lo,&hi);assert(lo>0&&hi>2);graph_axis_bounds(100,100,false,&lo,&hi);assert(lo<100&&hi>100);graph_axis_bounds(0,100,true,&lo,&hi);assert(lo<=0&&hi>=100);return 0;}
